function exportSave(){if(!state){message('Нет прохождения для экспорта.');return;}persist();const payload=dataRead()||{auto:state,checkpoint:state};const blob=new Blob([JSON.stringify(payload)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='posle-gudka-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function validSnapshot(s){return s&&s.version===1&&Number.isInteger(s.room)&&s.room>=0&&s.room<ROOMS.length&&Number.isFinite(s.hp)&&s.hp>=0&&s.hp<=100&&Number.isFinite(s.x)&&Number.isFinite(s.y)&&Array.isArray(s.bag)&&s.bag.every(a=>ITEMS[a.id]&&Number.isInteger(a.qty)&&a.qty>0&&a.qty<100&&Number.isInteger(a.x)&&a.x>=0&&a.x+ITEMS[a.id].w<=4&&Number.isInteger(a.y)&&a.y>=0&&a.y+ITEMS[a.id].h<=4)&&Array.isArray(s.notes)&&s.notes.every(n=>Number.isInteger(n)&&NOTES[n])&&Array.isArray(s.solved)&&s.solved.every(id=>PUZZLES[id])&&Array.isArray(s.keyItems)&&s.keyItems.every(k=>KEY_NAMES[k])&&Array.isArray(s.visited)&&s.visited.every(n=>ROOMS[n])&&ITEMS[s.equipped]?.weapon&&s.bag.some(a=>a.id===s.equipped)&&s.mag&&Number.isFinite(s.played)&&s.enemyState&&s.boss;}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{let text=await input.files[0].text();if(text.length>1000000)throw new Error('large');let parsed=JSON.parse(text);if(!validSnapshot(parsed.auto)||!validSnapshot(parsed.checkpoint))throw new Error('invalid');localStorage.setItem(STORAGE,JSON.stringify(parsed));state=parsed.auto;mode='game';closeModal();syncHUD();message('Сохранение загружено.');}catch(e){message('Не удалось загрузить. Нужен файл сохранения «После гудка».');}};input.click();}
$('#inventory').onclick=()=>{if(state&&mode==='game')inventory();};$('#journal').onclick=()=>{if(state&&mode==='game')journal();};$('#map').onclick=()=>{if(state&&mode==='game')map();};$('#equip').onclick=()=>{if(state&&mode==='game')equipNext();};$('#pause').onclick=()=>{if(state&&mode==='game'){if(modal.classList.contains('hidden'))pause();else closeAction();}};$('#brand').onclick=e=>{e.preventDefault();if(state&&mode==='game')pause();else menu();};$('#sound').onclick=()=>{initAudio();muted=!muted;if(audio)audio.master.gain.setTargetAtTime(muted?0:.22,audio.currentTime,.1);$('#sound').textContent='ЗВУК: '+(muted?'ВЫКЛ':'ВКЛ');};
function autoAim(){if(!state)return;let es=enemyList().filter(e=>e.alive);if(state.room===29&&!state.boss.dead)es.push(bossPosition());es.sort((a,b)=>Math.hypot(a.x-state.x,a.y-state.y)-Math.hypot(b.x-state.x,b.y-state.y));if(es[0])state.angle=Math.atan2(es[0].y-state.y,es[0].x-state.x);mouse.timer=2;}
